		return
	}
	n, _ := strconv.Atoi(fields[0])
	m, _ := strconv.Atoi(fields[1])

	if m < n {
		n += m
		m = n - m
		n -= m
	}

	g := 0
	f := 0
	f += n
	g += m - 1

	fmt.Println(g, f)
}

func readAll(r *os.File) (string, error) {
	var sb strings.Builder
	buf := make([]byte, 4096)
	for {
		n, err := r.Read(buf)
		if n > 0 {
			sb.Write(buf[:n])
		}
		if err != nil {
			break
		}
	}
	return sb.String(), nil
}

