		m = n - m
		n -= m
	}

	g := 0
	f := 0
	f += n
	g += m - 1

	fmt.Println(g, f)
}

func readAll(r interface{ Read([]byte) (int, error) }, buf []byte) (int, error) {
	total := 0
	for {
		n, err := r.Read(buf)
		total += n
		if err != nil {
			return total, err
		}
	}
}
